const inbound = $('Input').first().json;
const leads = $input.all().map(i => i.json);
function normalizePhone(p) { const raw = String(p || '').replace(/\D/g, ''); if (raw.length === 11 && raw.startsWith('1')) return raw.slice(1); return raw; }
const toE164 = (p) => { const d = String(p || '').replace(/\D/g, ''); if (d.length === 11 && d.startsWith('1')) return '+' + d; if (d.length === 10) return '+1' + d; return '+' + d; };
const inboundDigits = normalizePhone(inbound.fromPhone || inbound.e164Phone || '');
const match = leads.find(lead => { const status = String(lead['Status'] || '').trim(); if (!['New', 'Contacted'].includes(status)) return false; const leadPhone = normalizePhone(lead['Phone'] || ''); return leadPhone.length === 10 && leadPhone === inboundDigits; });
if (!match) { return [{ json: { leadFound: false, fromPhone: inbound.fromPhone, e164Phone: inbound.e164Phone, messageBody: inbound.messageBody } }]; }
return [{ json: { leadFound: true, leadId: match['Lead ID'] || '', firstName: match['First Name'] || '', lastName: match['Last Name'] || '', phone: toE164(match['Phone'] || ''), email: match['Email'] || '', address: match['Address'] || '', serviceNeeded: match['Service Needed'] || '', source: match['Source'] || '', fromPhone: inbound.fromPhone, e164Phone: inbound.e164Phone } }];

const s = $('Load Settings').first().json;
const leadData = $('Match YES Lead').first().json;
const render = (tpl, vars) => String(tpl || '').replace(/\{\{(\w+)\}\}/g, (_, k) => vars[k] ?? '');
const schedResults = $input.all().filter(i => i.json && i.json.confirmedDate);
const result = schedResults.length ? schedResults[0].json : null;
const schedulingFailed = !result;
const phone = leadData.phone || $('Input').first().json.e164Phone;
if (schedulingFailed) { const msg = render(s.sms_template_confirmation_failed, { firstName: leadData.firstName || 'there', businessName: s.business_name, appointmentTerm: s.appointment_term }); return [{ json: { to: phone, from: s.twilio_from_number, message: msg } }]; }
const dm = String(result.confirmedDate || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
let dateDisplay = result.confirmedDate;
if (dm) { const dt = DateTime.fromObject({ year: +dm[1], month: +dm[2], day: +dm[3] }, { zone: s.timezone }); dateDisplay = dt.toFormat('cccc, LLLL d'); }
const customerMsg = render(s.sms_template_confirmation_success, { firstName: leadData.firstName || '', appointmentTerm: s.appointment_term, dateDisplay, confirmedTime: result.confirmedTime, businessName: s.business_name, businessPhoneDisplay: s.business_phone_display || '' });
const ownerMsg = render(s.sms_template_lead_alert_success, { appointmentTerm: s.appointment_term, name: [leadData.firstName, leadData.lastName].filter(Boolean).join(' '), service: leadData.serviceNeeded || s.appointment_term, apptDisplay: dateDisplay + ' at ' + result.confirmedTime, phone });
return [{ json: { to: phone, from: s.twilio_from_number, message: customerMsg } }, { json: { to: s.owner_phone_e164, from: s.twilio_from_number, message: ownerMsg } }];

